#!/usr/bin/env python3
"""Verify generated bytes against a local, user-provided original executable."""
import argparse
import hashlib
from pathlib import Path
import unittest

from make_patch import FIXED_SHA256, ORIGINAL_SHA256, build


class PatchTests(unittest.TestCase):
    def test_input_version_is_locked(self):
        with self.assertRaisesRegex(ValueError, 'SHA-256'):
            build(b'not the supported executable')

    def test_output_is_reproducible(self):
        original = self.original.read_bytes()
        self.assertEqual(hashlib.sha256(original).hexdigest(), ORIGINAL_SHA256)
        fixed = build(original)
        self.assertEqual(hashlib.sha256(fixed).hexdigest(), FIXED_SHA256)
        self.assertEqual(len(fixed), len(original))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--exe', type=Path, required=True,
                        help='Path to your own, unmodified WRMS.EXE')
    args = parser.parse_args()
    PatchTests.original = args.exe
    unittest.main(argv=['test_patch.py'], verbosity=2)


if __name__ == '__main__':
    main()